(() => {'use strict';const g=()=>window.gameDebug,$=id=>document.getElementById(id);
function modal(text,options){$('modal-title').textContent='Пропавший послушник';$('modal-body').replaceChildren();const p=document.createElement('p');p.textContent=text;$('modal-body').append(p);for(const o of options){const b=document.createElement('button');b.textContent=o.label;b.disabled=!!o.disabled;b.onclick=()=>{$('modal').close();o.fn();};$('modal-body').append(b);}$('modal').showModal();}
function refresh(message){if(message)g().tell(message);g().save();g().render();}
function start(){if(g().busy||g().state.combat)return;window.Scenario?.stop(false);g().state.episode={stage:'investigate',attempts:{},clues:[],minutes:0};g().enterScene('hub');refresh('Эллен: «Лин не вернулся из северного крыла. Расспросите меня, проверьте следы возле лестницы или осмотрите запертую дверь».');window.viewsDebug.switchTab('map');}
function open(){const e=g().state.episode;if(!e)return modal('Лин, молодой послушник, пропал. Найдите способ попасть в крипту, найдите его и вернитесь к Эллен. Это сценарный эпизод.',[{label:'Начать эпизод',fn:start}]);modal(e.stage==='done'?'Лин найден. Эллен получила его записи. Эпизод завершён.':e.stage==='report'?'Лин жив и ждёт у выхода. Вернитесь к Эллен и сообщите об этом.':e.unlocked?'Северный проход открыт. Найдите Лина в крипте.':'Три пути: расспросить Эллен, изучить следы или открыть замок.',[{label:'Показать цель',fn:focus},{label:'Закрыть',fn:()=>{}}]);}
function focus(){const e=g().state.episode;if(!e)return;if(e.stage==='report'){if(g().state.scene!=='hub'){const p=g().props.find(p=>p.type==='portal');g().select(p);window.camera?.center(p);}else{const p=g().props.find(p=>p.id==='keeper');g().select(p);window.camera?.center(p);}}else{const p=g().props.find(p=>p.id===(g().state.scene==='crypt'?'novice':e.unlocked?'portal':'episode-tracks'));if(p){g().select(p);window.camera?.center(p);}}}
function bonus(id){const a=g().active(),[stat]=DND.skills[id];return DND.mod(a.stats[stat])+(a.skills.includes(id)?DND.pb(g().state.level):0);}
function ask(){const e=g().state.episode;if(!e)return open();if(e.stage==='report')return complete();if(e.stage==='done'||e.unlocked)return open();const key=g().active().id+':persuasion';modal('Эллен скрывает, что Лин искал записи о колоколе. Успех: она даёт ключ. Неудача: можно изучить следы или заняться замком.',[{label:'Убеждение '+signed(bonus('persuasion'))+' · СЛ 10',disabled:!!e.attempts[key],fn:()=>{if(e.attempts[key])return;e.attempts[key]=true;const r=DND.skill(g().active(),'persuasion',10,g().state.level,g().state.advantage||0);g().report(r.text);if(r.success){e.key=true;e.unlocked=true;e.route='Разговор';e.clues.push('Лин ищет записи в крипте');refresh('Эллен даёт ключ: «Он спустился в крипту за журналом настоятеля».');}else refresh('Эллен колеблется. Проверьте следы у лестницы или замок северной двери.');}},{label:'Показать следы',fn:focus}]);}
function signed(n){return (n>=0?'+':'')+n;}
function tracks(){const e=g().state.episode;if(!e||e.stage!=='investigate'){refresh('Свежие следы ведут к северной лестнице.');return;}const r=DND.skill(g().active(),'survival',10,g().state.level,g().state.advantage||0);g().report(r.text);e.unlocked=true;e.route='Следы';e.clues.push('Следы Лина у северной лестницы');if(!r.success)e.minutes+=10;refresh(r.success?'Следы ведут к крипте. В пыли найден запасной ключ от северной двери.':'Через десять минут поиска вы находите следы и выпавший запасной ключ. Путь открыт.');e.key=true;g().save();}
function portal(p){const e=g().state.episode;if(g().state.scene!=='hub'||!e||e.stage!=='investigate'||e.unlocked)return false;const a=g().active();modal('Северная дверь заперта. Проверки можно заменить поиском ключа: расспросить Эллен или изучить следы. Провал создаёт шум и занимает 10 минут.',[['dex',12,'Открыть замок'],['str',13,'Выбить дверь']].map(([stat,dc,name])=>({label:name+' · '+DND.labels[stat]+' '+signed(DND.mod(a.stats[stat]))+' · СЛ '+dc,disabled:!!e.attempts[a.id+':'+stat],fn:()=>{const k=a.id+':'+stat;if(e.attempts[k])return;e.attempts[k]=true;const r=DND.test(DND.mod(a.stats[stat]),dc,g().state.advantage||0);g().report(a.name+' · '+name+'\n'+r.text);if(r.success){e.unlocked=true;e.route=name;refresh('Северная дверь открыта. Можно спуститься в крипту.');}else{e.minutes+=10;e.noise=true;refresh('Не удалось. Шум разносится по крылу. Попробуйте другой способ или найдите ключ.');}}})));return true;}
function rescue(p){const e=g().state.episode;if(!e)return modal('Лин отдыхает в крипте. Запустите эпизод через меню.',[{label:'Закрыть',fn:()=>{}}]);if(e.stage==='done'||e.stage==='report')return open();e.stage='report';e.clues.push('Журнал настоятеля');refresh('Лин найден живым. Он даёт журнал: колокол увезли на север. Вернитесь к Эллен.');window.openObjectDialogue({name:'Лин · послушник',description:'«Я искал журнал и захлопнул за собой дверь. Спасибо! Теперь я знаю путь к выходу. Отнесите эти записи Эллен». Лин уходит к северной лестнице.'});}
function complete(){const e=g().state.episode;if(!e||e.stage!=='report'||g().state.scene!=='hub')return;e.stage='done';if(!g().state.episodeRewarded){g().state.gold+=25;g().state.xp+=40;g().state.episodeRewarded=true;}refresh('Эллен: «Лин жив, а записи подтверждают северный след». Эпизод завершён. Награда за первое прохождение: 25 монет и 40 опыта.');window.openObjectDialogue({name:'Эллен · хранительница',description:'«Спасибо, что нашли Лина. Теперь мы можем искать колокол на севере». Послушник спасён, журнал остаётся в хронике.'});}
function render(){const e=g()?.state.episode;const b=$('episode-status');if(!b)return;b.hidden=!e;if(e)b.textContent=e.stage==='done'?'Пропавший послушник · завершено':e.stage==='report'?'Лин найден · вернитесь к Эллен':e.unlocked?'Найдите Лина в крипте':'Пропавший послушник · найдите путь';b.onclick=open;}
window.Episode={start,open,ask,tracks,portal,rescue,complete,render};})();
